const fs = await import('node:fs').catch(() => null);
// Read the DSL file content to pass to the structurizr tools
const { read } = await import('node:fs/promises').catch(async () => ({ read: null }));
let dsl;
try {
  dsl = await read('/work/workspace.dsl', 'utf8');
} catch (e) {
  dsl = null;
}
if (!dsl) {
  return { error: 'could not read file' };
}
const [validate, inspect] = await Promise.allSettled([
  tools.structurizr.validate({ dsl }),
  tools.structurizr.inspect({ dsl }),
]);
return {
  validate: validate.status === 'fulfilled' ? validate.value : { error: validate.reason },
  inspect: inspect.status === 'fulfilled' ? inspect.value : { error: inspect.reason },
};

